//! Byte gate: every embedded preset has a committed Workflow IR twin under `ir-twins/`, and the
//! twin is the adapter's canonical output for that bundle.
//!
//! Four drift classes, one test each: a preset with no twin, a twin naming no preset, a twin that
//! is not its own canonical serialization (hand-edited), and a twin that no longer matches
//! `import_preset_bundle` for its bundle — stale after a `preset.yaml` or referenced prompt/template
//! byte changed. The twin is generated by `nexus42 preset export-ir`; this gate never writes.
//!
//! "Canonical" is [`nexus_preset::canonical_twin_json`], the one serializer the generator also
//! calls, so the bytes agree no matter which build produced them. The stale check covers referenced
//! asset bytes, not just `preset.yaml`, because the imported document carries a BLAKE3
//! `content_hash` per asset.

use std::path::{Path, PathBuf};

use nexus_preset::manifest::PresetManifest;
use nexus_preset::{canonical_twin_json, import_preset_bundle, FsAssetSource};
use nexus_workflow_ir::WorkflowDocument;

/// Suffix of one twin file: `<id>.workflow.ir.json`, the fixture convention.
const TWIN_SUFFIX: &str = ".workflow.ir.json";

fn preset_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("embedded-presets")
}

fn twin_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("ir-twins")
}

/// Embedded preset ids (sorted): every directory under `embedded-presets/` holding a `preset.yaml`.
fn preset_ids() -> Vec<String> {
    let mut ids: Vec<String> = std::fs::read_dir(preset_root())
        .expect("read embedded-presets/")
        .filter_map(Result::ok)
        .filter(|entry| entry.path().join("preset.yaml").is_file())
        .map(|entry| entry.file_name().to_string_lossy().into_owned())
        .collect();
    ids.sort();
    ids
}

/// Twin file names in `ir-twins/` (sorted), suffix included.
fn twin_files() -> Vec<String> {
    let mut names: Vec<String> = std::fs::read_dir(twin_root())
        .expect("read ir-twins/")
        .filter_map(Result::ok)
        .filter(|entry| entry.path().is_file())
        .map(|entry| entry.file_name().to_string_lossy().into_owned())
        .collect();
    names.sort();
    names
}

/// The id a twin file name names, or `None` when the name does not carry [`TWIN_SUFFIX`].
fn twin_id(file_name: &str) -> Option<&str> {
    file_name.strip_suffix(TWIN_SUFFIX)
}

/// Canonical twin bytes for one bundle: `import_preset_bundle`'s document as pretty JSON plus one
/// trailing newline, the serialization `workflow_ir_round_trip.rs` asserts for its fixtures.
fn canonical_twin(id: &str) -> Result<String, String> {
    let bundle = preset_root().join(id);
    let manifest_path = bundle.join("preset.yaml");
    let yaml = std::fs::read_to_string(&manifest_path)
        .map_err(|error| format!("read {}: {error}", manifest_path.display()))?;
    let manifest: PresetManifest = serde_yaml::from_str(&yaml)
        .map_err(|error| format!("parse {}: {error}", manifest_path.display()))?;
    let source = FsAssetSource::new(&bundle).map_err(|error| format!("open `{id}`: {error}"))?;
    let imported = import_preset_bundle(&manifest, &source)
        .map_err(|error| format!("import `{id}` at {}: {error}", bundle.display()))?;
    canonical_twin_json(&imported.document).map_err(|error| format!("serialize `{id}`: {error}"))
}

/// Index of the first differing byte, or `None` when equal.
fn first_difference(a: &[u8], b: &[u8]) -> Option<usize> {
    a.iter()
        .zip(b.iter())
        .position(|(left, right)| left != right)
        .or_else(|| (a.len() != b.len()).then(|| a.len().min(b.len())))
}

#[test]
fn every_preset_has_an_ir_twin() {
    let missing: Vec<String> = preset_ids()
        .into_iter()
        .filter(|id| !twin_root().join(format!("{id}{TWIN_SUFFIX}")).is_file())
        .collect();
    assert!(
        missing.is_empty(),
        "preset(s) with no committed IR twin in ir-twins/ (run `nexus42 preset export-ir <bundle> --out crates/nexus-preset/ir-twins/<id>.workflow.ir.json`): {missing:?}"
    );
}

#[test]
fn every_twin_names_a_preset() {
    let presets = preset_ids();
    let files = twin_files();
    let orphans: Vec<&str> = files
        .iter()
        .filter(|file_name| {
            twin_id(file_name).is_none_or(|id| !presets.iter().any(|preset| preset.as_str() == id))
        })
        .map(String::as_str)
        .collect();
    assert!(
        orphans.is_empty(),
        "twin file(s) naming no preset under embedded-presets/: {orphans:?}"
    );
}

#[test]
fn every_twin_is_canonical() {
    let mut failures = Vec::new();
    for file_name in twin_files() {
        let Some(id) = twin_id(&file_name) else {
            continue; // `every_twin_names_a_preset` owns the name shape.
        };
        if !preset_root().join(id).is_dir() {
            continue; // orphan; owned by `every_twin_names_a_preset`.
        }
        let path = twin_root().join(&file_name);
        let committed = std::fs::read(&path).expect("read twin");
        let document: WorkflowDocument = match serde_json::from_slice(&committed) {
            Ok(document) => document,
            Err(error) => {
                failures.push(format!(
                    "{file_name}: does not deserialize as a WorkflowDocument: {error}"
                ));
                continue;
            }
        };
        let canonical = canonical_twin_json(&document).expect("serialize the committed twin");
        if canonical.as_bytes() != committed.as_slice() {
            failures.push(format!(
                "{file_name}: not canonical (first difference at byte {:?})",
                first_difference(committed.as_slice(), canonical.as_bytes())
            ));
        }
    }
    assert!(
        failures.is_empty(),
        "twin file(s) that are not their own canonical serialization: {failures:#?}"
    );
}

#[test]
fn every_twin_matches_its_preset() {
    let mut failures = Vec::new();
    for id in preset_ids() {
        let path = twin_root().join(format!("{id}{TWIN_SUFFIX}"));
        if !path.is_file() {
            continue; // missing; owned by `every_preset_has_an_ir_twin`.
        }
        let expected = match canonical_twin(&id) {
            Ok(expected) => expected,
            Err(failure) => {
                failures.push(failure);
                continue;
            }
        };
        let committed = std::fs::read(&path).expect("read twin");
        if committed != expected.as_bytes() {
            failures.push(format!(
                "`{id}` twin is stale (first difference at byte {:?}); regenerate it with `nexus42 preset export-ir`",
                first_difference(committed.as_slice(), expected.as_bytes())
            ));
        }
    }
    assert!(
        failures.is_empty(),
        "twin(s) drifted from their preset bundle: {failures:#?}"
    );
}
